def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers

    Args:
        n (int): The number to check

    Returns:
        bool: True if n can be written as the sum of 4 positive even numbers, False otherwise
    """
    def is_even(x):
        return x % 2 == 0

    n = abs(n)  # Convert to positive
    target = n // 4
    for i in range(target + 1):
        for j in range(i + 1, target + 1):
            for k in range(j + 1, target + 1):
                for m in range(k + 1, target + 1):
                    if i + j + k + m == n and is_even(i) and is_even(j) and is_even(k) and is_even(m):
                        return True
    return False

