from collections import deque
import copy

def minPath(grid, k):
    N = len(grid)
    directions = [[-1, 0], [1, 0], [0, -1], [0, 1]]
    memo = {}

    def dfs(i, j, k, visited):
        key = (i, j, k, tuple(visited))
        if key in memo:
            return memo[key]
        if k == 0:
            return []
        paths = []
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N:
                if not visited[ni*nj]:
                    next_path = copy.copy(visited)
                    next_path[i*j] = False
                    next_path[ni*nj] = True
                    path = dfs(ni, nj, k-1, next_path)
                    if path:
                        paths.append([grid[i][j]] + path)
        if not paths:
            memo[key] = [[]]
        else:
            memo[key] = min(paths, key=lambda x: x[0] > x[1])
        return memo[key]

    visited = [[False for _ in range(N)] for _ in range(N)]
    visited = [visited]
    for i in range(N):
        for j in range(N):
            visited.append([visited[i][j]])

    return dfs(0, 0, k, visited)

