from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    grid50 = [i * n + j + 1 for i in range(n) for j in range(n)]
    directions = [[-1, 0], [0, -1], [1, 0], [0, 1]]

    def isValid(x, y):
        return 0 <= x < n and 0 <= y < n

    def helper(x, y, count):
        if count == k:
            return [grid[x][y]]
        if count > k:
            return None
        path = []
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if isValid(nx, ny) and grid50[nx * n + ny] > grid50[n * n + y]:
                tmp = helper(nx, ny, count + 1)
                if tmp is not None:
                    tmp.insert(0, grid[x][y])
                    return tmp
        return None

    for y in range(n):
        for x in range(n):
            if grid50[x * n + y] == 1:
                res = helper(x, y, 0)
                if res is not None:
                    return res
