from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def parse_depth(group: str) -> int:
        depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                depth += 1
                max_depth = max(max_depth, depth)
            elif char == ')':
                depth -= 1
        return max_depth

    return [parse_depth(group) for group in paren_string.split()]
