from datetime import datetime

def valid_date(date_str):
    # Split the date string into day, month and year
    try:
        date, month, year = map(int, date_str.split('-'))

        # Validate if the date year is valid
        max_year = 2024
        current_year = datetime.now().year
        min_year = datetime.now().year - current_year % 100 - 19
        if year < min_year or year > max_year:
            return False

        # Is the day (1-31) valid for month and year
        def is_dValid(day, month, year):
            if month in [1,3,5,7,8,10,12]:
                return 1 <= day <= 31
            elif month in [4,6,9,11]:
                return 1 <= day <= 30
            else:
                return 1 <= day <= 29

        if not is_dValid(date, month, year):
            return False

    # If the date string is not in the correct format
    except ValueError:
        return False

    # If no errors found then check if month is between 1-12
    # Check if valid month and year
    return 1 <= month <= 12
