from typing import List

def tri(n: int) -> List[int]:
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]
    elif n == 2:
        return [1, 3, 2]
    else:
        trib_sequence = [1, 3, 2]
        for i in range(3, n + 1):
            if i % 2 == 0:
                trib_sequence.append(1 + i // 2)
            else:
                trib_sequence.append(trib_sequence[i - 3] + trib_sequence[i - 2] + trib_sequence[i - 1])
        return trib_sequence
