from typing import List

def factorize(n: int) -> List[int]:
    def get_factors(num: int) -> List[int]:
        factors = []
        for i in range(2, num + 1):
            while num % i == 0:
                num //= i
                factors.append(i)
        return factors

    num_factors = []
    i = 2
    while i * i <= n:
        num_factors.extend(get_factors(n // i))
        i += 1
    if n > 1:
        num_factors.extend(get_factors(n))
    return list(set(num_factors))
