from typing import List

def factorize(n: int) -> List[int]:
    def get_factors(num: int) -> List[int]:
        factors = []
        for i in range(2, int(num**0.5) + 1):
            while num % i == 0:
                factors.append(i)
                num //= i
        if num > 1:
            factors.append(num)
        return factors

    factors = get_factors(n)
    factor_counts = {}
    for factor in factors:
        if factor in factor_counts:
            factor_counts[factor] += 1
        else:
            factor_counts[factor] = 1

    return [factor for factor, count in factor_counts.items() for _ in range(count)]

