import math

def prime_length(string):
    """
    Returns True if the string length is a prime number, False otherwise
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        sqrt_n = math.isqrt(n)
        for i in range(3, sqrt_n + 1, 2):
            if n % i == 0:
                return False
        return True

    string_length = len(string)
    return is_prime(string_length)
```

