```python
def histogram(text):
    counts = {}
    words = text.split()
    for word in words:
        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1
    if max(counts.values()) > 1:
        max_count_key = [key for (key, value) in counts.items() if value == max(counts.values())]
        return {key: values() for key, values() in {key: counts[str(key)] for key in max_count_key}.items()}
    else:
        return {}
```

