import re

def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return re.split(',| ', txt)
    else:
        lower_case_letters = [i for i, char in enumerate(txt) if char.islower()]
        return len([letter for letter in lower_case_letters if (letter - ord('a') + 1) % 2 != 0])
