def prime_fib(n: int):
    """
    Returns the nth number that is a Fibonacci number and it's also prime.
    """
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    a, b = 0, 1
    while True:
        a, b = b, a + b
        if is_prime(b) and b >= n:
            return b
