from math import sqrt

def prime_fib(n: int):
    """
    Returns the n-th number that is a Fibonacci number and it's also prime.
    """
    def is_prime(num: int) -> bool:
        if num < 2: 
            return False
        for i in range(2, int(sqrt(num)) + 1):
            if num % i == 0: 
                return False
        return True

    fib, count = 0, 0
    a, b = 0, 1
    while count < n:
        a, b = b, a + b
        if is_prime(b):
            fib += 1
            if fib == n:
                return b
    return None
