import math

def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    if a <= 1:
        return False
    prr = set()
    for i in range(2, a+1):
        if is_prime(i):
            if a % (i*i*i) == 0:
                prr.add(i)
                a = a//i//i
                if a == 1:
                    return len(prr) == 3 and all(is_prime(num) for num in prr)
    return False
