        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        sqrt_n = math.sqrt(n)
        for i in range(3, int(sqrt_n) + 1, 2):
            if n % i == 0:
                return False
        return True

    for i in range(2, a):
        if a % (i * i) == 0:
            for j in range(2, int(math.sqrt(a / i)) + 1):
                if i % j == 0 and is_prime(i // j) and is_prime(j):
                    return True
    return False
