def get_odd_collatz(n):
    if n <= 0:
        return []

    seen = set()
    queue = deque([(n, 1)])

    odd_numbers = []

    while queue:
        num, step = queue.popleft()

        if num in seen:
            while len(odd_numbers) < step:
                odd_numbers.append(odd_numbers[-1])
        else:
            seen.add(num)

            if num % 2 == 0:
                queue.append((num // 2, step + 1))
            else:
                odd_numbers.append(num)
                new Previous_value = num -3
                if new Previous_value > 0:
                    newstep = step + 1
                    queue.append((new Previous_value, newstep))

    return sorted(odd_numbers)
