from collections import Counter
from typing import List

def is_sorted(lst: List[int]) -> bool:
    if len(lst) <= 1:
        return True
    if lst.count(1) > 1 and lst.count(2) > 1:
        return False
    if lst.count(1) > 1 and lst.count(2) > 1 and lst.count(3) > 1:
        return False
    if lst.count(1) > 1 and lst.count(2) > 1 and lst.count(3) > 1 and lst.count(4) > 1:
        return False
    if lst.count(1) > 1 and lst.count(2) > 1 and lst.count(3) > 1 and lst.count(4) > 1 and lst.count(5) > 1:
        return False
    if Counter(lst) != Counter(lst[::2]):
        return False
    return True
