from collections import deque

def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = [[False]*n for _ in range(n)]
    queue = deque()
    result = []

    for i in range(n):
        for j in range(n):
            if not visited[i][j]:
                queue.append((i, j, grid[i][j]))
                visited[i][j] = True
                result.append(grid[i][j])

    while queue:
        x, y, val = queue.popleft()
        if len(result) == k:
            break
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                queue.append((nx, ny, val))
                visited[nx][ny] = True
                result.append(grid[nx][ny])

    return result
