from typing import List

def factorize(n: int) -> List[int]:
    def prime_factors(num: int, i: int = 2) -> List[int]:
        factors = []
        while i * i <= num:
            if num % i:
                i += 1
            else:
                num //= i
                factors.append(i)
        if num > 1:
            factors.append(num)
        return factors

    factors_dict = {}
    for factor in prime_factors(n):
        factors_dict[factor] = factors_dict.get(factor, 0) + 1

    return list(factors_dict.values())

