def match_parens(lst):
    def is_good(s):
        stack = deque()
        for c in s:
            if c == '(':
                stack.append(c)
            elif c == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    return 'Yes' if is_good(lst[0]) and is_good(lst[1]) else 'No'
