from collections import deque

def exchange(lst1, lst2):
    even_lst1 = [num for num in lst1 if num % 2 == 0]
    even_lst2 = [num for num in lst2 if num % 2 == 0]

    if len(even_lst1) == len(lst1):
        return "YES"

    queue = deque([(lst1, lst2, 0)])
    visited = set((tuple(lst1), tuple(lst2)))

    while queue:
        lst1_copy, lst2_copy, step = queue.popleft()

        if len(lst1_copy) == 0:
            return "NO"

        if len(lst2_copy) == 0:
            if len(lst1_copy) > 0 and len(lst1_copy) % 2 == 0:
                return "YES"

        for i in range(len(lst1_copy)):
            num1 = lst1_copy[i]
            num2 = lst2_copy[0]
            lst1_copy[i], lst2_copy[0] = num2, num1
            if (tuple(lst1_copy), tuple(lst2_copy)) not in visited:
                queue.append((lst1_copy, lst2_copy, step + 1))
                visited.add((tuple(lst1_copy), tuple(lst2_copy)))
            lst1_copy[i], lst2_copy[0] = num1, num2

    return "NO"
