from itertools import islice, repeat

def exchange(lst1, lst2):
    def is_even(x):
        return x % 2 == 0

    def is_all_even(lst):
        return all(is_even(x) for x in lst)

    def is_possible(lst1, lst2, count=1000):
        if is_all_even(lst1):
            return "YES"
        if not lst2:
            return "NO"
        elements = islice(repeat(1, 1000), count)
        if is_all_even(lst1 + list(islice(lst2, count))):
            return "YES"
        return "NO"

    return is_possible(lst1, lst2)
