from collections import Counter

def find_max(words):
    max_len = 0
    max_word = ""
    for word in words:
        unique_chars = len(Counter(word))
        if unique_chars > max_len:
            max_len = unique_chars
            max_word = word
        elif unique_chars == max_len:
            if word < max_word:
                max_word = word
    return max_word
