def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shifted_alphabet = alphabet[2:] + alphabet[:2]
    result = ''
    for char in s:
        if char.isalpha():
            if char.islower():
                result += shifted_alphabet[alphabet.index(char)]
            else:
                result += shifted_alphabet[alphabet.index(char.lower())].upper()
        else:
            result += char
    return result
```

```python
def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shift = 2
    result = ''
    for char in s:
        if char.isalpha():
            if char.islower():
                index = (alphabet.index(char) + shift) % 26
                result += alphabet[index]
            else:
                index = (alphabet.index(char.lower()) + shift) % 26
                result += alphabet[index].upper()
        else:
            result += char
    return result
```

