def skjkasdkd(lst):
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    max_prime = max([n for n in lst if is_prime(n)])
    return sum(int(digit) for digit in str(max_prime))

```

