def sum_of_digits_of_largest_prime(lst):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [num for num in lst if is_prime(num)]
    largest_prime = max(primes) if primes else None
    return sum(int(digit) for digit in str(largest_prime) if digit.isdigit()) if largest_prime else None
