from collections import Counter

def find_max(words):
    def count_unique_chars(word):
        return len(Counter(word))

    max_length = max(count_unique_chars(word) for word in words)
    max_words =sorted((word for word in words if count_unique_chars(word) == max_length))
    return max_words[0] if max_words else ""
