def find_max(words):
    def num_unique_chars(word):
        return len(set(word))

    max_string = max((word for word in words if num_unique_chars(word) == 
                      max(num_unique_chars(w) for w in words)), key=lambda x: x)

    max_num_unique_chars = max(num_unique_chars(w) for w in words if num_unique_chars(w) == 
                                max(num_unique_chars(w) for w in words))

    return max_string if max(num_unique_chars(w) for w in words) == max_num_unique_chars else ""
```

