def find_max(words):
    def unique_chars(s):
        return len(set(s))

    max_unique = max(unique_chars(word) for word in words, key=str.lower)
    result = next(word for word in words if unique_chars(word) == max_unique)
    return result if result else ""
```

```python
def find_max(words):
    def unique_chars(word):
        return len(set(word))

    max_unique = max(unique_chars(word) for word in words)
    max_words = [word for word in words if unique_chars(word) == max_unique]

    if max_words:
        return min(max_words)
    else:
        return ""
```

