```python
from typing import List

def unique_digits(x: List[int]) -> List[int]:
    unique = set()
    for num in x:
        for digit in str(num):
            if int(digit) % 2 == 0:
                break
        else:
            unique.add(num)
    return sorted(list(unique))
```

