from collections import deque

def exchange(lst1, lst2):
    queue = deque([(lst1, lst2, False)])
    visited = set((tuple(lst1), tuple(lst2)))

    while queue:
        current_lst1, current_lst2, is_even = queue.popleft()

        if all(num % 2 == 0 for num in current_lst1):
            return "YES"

        for i in range(len(current_lst1)):
            for j in range(len(current_lst2)):
                new_lst1 = current_lst1.copy()
                new_lst2 = current_lst2.copy()

                new_lst1[i], new_lst2[j] = new_lst2[j], new_lst1[i]

                if (tuple(new_lst1), tuple(new_lst2)) not in visited:
                    queue.append((new_lst1, new_lst2, is_even))
                    visited.add((tuple(new_lst1), tuple(new_lst2)))

    return "NO"
```

