def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([(i, j, grid[i][j], set())])
    visited = set((i, j))
    res = None
    while queue:
        x, y, val, path = queue.popleft()
        if len(path) == k:
            if res is None or path < res:
                res = path
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                queue.append((nx, ny, grid[nx][ny], path | {(nx, ny)}))
                visited.add((nx, ny))
    return list(res)
