def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    res = []
    visited = set()

    def dfs(i, j, path, k):
        if len(path) == k:
            return path
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n and (ni, nj) not in visited:
                visited.add((ni, nj))
                res = dfs(ni, nj, path + [grid[ni][nj]], k)
                visited.remove((ni, nj))

        return res

    for i in range(n):
        for j in range(n):
            if (i, j) not in visited:
                res = dfs(i, j, [grid[i][j]], k)
                break

    return res
