from typing import Union

def fibfib(n: int) -> Union[int, None]:
    if n < 3:
        return 0
    fibfib_dict = {0: 0, 1: 0, 2: 1}
    while n > 2:
        fibfib_dict[n] = fibfib_dict[n - 1] + fibfib_dict[n - 2] + fibfib_dict[n - 3]
        n -= 1
    return fibfib_dict[n]
