from typing import List
import re


def parse_nested_parens(paren_string: str) -> List[int]:
    def get_max_depth(group: str) -> int:
        if('(' not in group or ')' not in group):
            return 0
        left, right = group.count('('), group.count(')')
        if left != right:
            return 0
        min_depth = float('inf')
        for char in group:
            if char == '(':
                min_depth = min(min_depth, 1 + get_max_depth(group[group.index(char) + 1:]))
            elif char == ')':
                min_depth = min(min_depth, 1 + get_max_depth(group[:group.index(char)-1]))
                break
        return min_depth + 1


    return [get_max_depth(g) for g in re.split(' \(| \)\)', paren_string)] 
