def max_fill(grid, capacity):
    import math
    def helper(i, j, count):
        if i == len(grid):
            return count
        if j == len(grid[0]):
            return helper(i + 1, 0, count)
        if grid[i][j] == 0:
            return helper(i, j + 1, count)
        if grid[i][j] == 1:
            count += 1
            grid[i][j] = 0
            return helper(i, j + 1, count)
        return helper(i, j + 1, count)
    return helper(0, 0, 0)
