from functools import reduce

def exchange(lst1, lst2):
    def has_even(lst):
        return all(x % 2 == 0 for x in lst)

    def has_odd(lst):
        return any(x % 2 != 0 for x in lst)

    def can_exchange(lst1, lst2):
        return (has_even(lst1) and has_odd(lst2)) or (has_odd(lst1) and has_even(lst2))

    return "YES" if can_exchange(lst1, lst2) else "NO"
