from itertools import groupby
from typing import List

def is_nested(string: str) -> bool:
    pairs: List[str] = list(string)
    open_brackets, closed_brackets = [], []

    for i, bracket in enumerate(pairs):
        if bracket == '[':
            open_brackets.append(i)
        elif bracket == ']':
            if not open_brackets:
                return False
            closed_brackets.append(i)
            open_brackets.pop()

    return len(closed_brackets) > 0
```

