from collections import deque

def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    res = []
    queue = deque()
    visited = [[False]*n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if not visited[i][j]:
                queue.append((i, j, grid[i][j]))
                visited[i][j] = True
                res.append(grid[i][j])

    while queue:
        x, y, val = queue.popleft()
        if len(res) == k:
            return res
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                queue.append((nx, ny, val))
                visited[nx][ny] = True
                res.append(grid[nx][ny])

    return res
```

