from collections import defaultdict, deque

def get_row(lst, x):
    def find_coordinates(data, target):
        coordinates = []
        for i, row in enumerate(data):
            if target in row:
                coordinates.append((i, row.index(target)))
        return coordinates

    def sort_coordinates(coordinates):
        sorted_coordinates = sorted(coordinates, key=lambda x: (x[0], len(x[1]), -x[1].index(target)))

        sorted_by_column = []
        for row, column in sorted_coordinates:
            if not sorted_by_column or sorted_by_column[-1][1] != column:
                sorted_by_column.append((row, column))
            else:
                left_index = sorted_by_column[-1][1]
                right_index = len(x) - 1 - sorted_by_column[-1][1]
                for i in range(left_index, right_index + 1):
                    if x[i] == column[1]:
                        sorted_by_column.append((row, sorted_by_column[-1][1]))
                        break
        return sorted_by_column

    def main():
        result = []
        target = x
        x_set = set()
        for row in lst:
            if row:
                for i, element in enumerate(row):
                    if element == target:
                        if element not in x_set:
                            x_set.add(element)
                            result.append((lst.index(row), i))
        return sort_coordinates(result)

    result = main()
    return [(row, column) for row, column in result]

