from enum import Enum
from typing import Union, Optional

class NumberType(Enum):
    INT = 1
    FLOAT = 2
    STRING = 3

def compare_one(a: Union[float, int, str], b: Union[float, int, str]) -> Optional[Union[float, int, str]]:
    """
    Create a function that takes integers, floats, or strings representing 
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """
    a_type = NumberType.INT if isinstance(a, int) else NumberType.FLOAT if isinstance(a, float) else NumberType.STRING
    b_type = NumberType.INT if isinstance(b, int) else NumberType.FLOAT if isinstance(b, float) else NumberType.STRING

    if a_type == b_type:
        if a == b:
            return None
        elif a > b:
            return a
        else:
            return b
    else:
        if a_type == NumberType.INT:
            if isinstance(b, float):
                return float(b)
            elif isinstance(b, str):
                if ',' in b:
                    return float(b.replace(',', '.'))
                elif '.' in b:
                    return float(b.replace('.', ','))
                else:
                    return float(b)
            else:
                return max(int(a), int(b))
        elif a_type == NumberType.FLOAT:
            if isinstance(b, int):
                return float(b)
            elif isinstance(b, str):
                if ',' in b:
                    return float(b.replace(',', '.'))
                elif '.' in b:
                    return float(b.replace('.', ','))
                else:
                    return float(b)
            else:
                return max(a, b)
        elif a_type == NumberType.STRING:
            if isinstance(b, int):
                return b
            elif isinstance(b, float):
                return float(b)
            elif isinstance(b, str):
                if ',' in b:
                    return b
                elif '.' in b:
                    return b
                else:
                    return max(a, b)

