def get_odd_collatz(n: int) -> List[int]:
    def collatz(num: int) -> List[int]:
        sequence = [num]
        while num != 1:
            if num % 2 == 0:
                num = num // 2
            else:
                num = 3 * num + 1
            sequence.append(num)
        return sequence

    return sorted([x for x in range(1, n + 1) if collatz(x) % 2 != 0])
