import math

def skjkasdkd(lst):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    max_prime = max(lst, key=lambda x: x if is_prime(x) else float('-inf'))
    return sum(int(digit) for digit in str(max_prime))

