from typing import Union, Optional

def compare_one(a: Union[int, float, str], b: Union[int, float, str]) -> Optional[Union[int, float, str]]:
    def float_or_int(x: Union[int, float]) -> Union[int, float]:
        if isinstance(x, int):
            return x
        elif isinstance(x, float):
            return x
        else:
            return None

    def string_to_float(x: str) -> float:
        if ',' in x:
            x = x.replace(',', '.')
        try:
            return float(x)
        except ValueError:
            return None

    a = float_or_int(a)
    b = float_or_int(b)
    if a is None or b is None:
        return None

    if isinstance(a, str) and isinstance(b, str):
        a = string_to_float(a)
        b = string_to_float(b)
    elif isinstance(a, str):
        a = string_to_float(a)
    elif isinstance(b, str):
        b = string_to_float(b)

    if a > b:
        return a
    elif a < b:
        return b
    else:
        return None
