def max_fill(grid, capacity):
    import math
    def helper(grid, capacity, row, col, steps):
        if row == len(grid):
            return steps
        for c in range(col, len(grid[row])):
            if grid[row][c] == 1:
                grid[row][c] = 0
                if c + 1 < len(grid[row]) and grid[row][c + 1] == 1:
                    steps = max(steps, helper(grid, capacity, row, c + 1, steps + 1))
                steps = max(steps, helper(grid, capacity, row + 1, 0, steps + 1))
        return steps

    return helper(grid, capacity, 0, 0, 0)
