    def helper(row, bucket_count):
        if row == len(grid):
            return bucket_count
        min_bucket_count = float('inf')
        for j in range(len(grid[0])):
            if grid[row][j] == 1:
                min_bucket_count = min(min_bucket_count, bucket_count + (len(grid) - row - 1))
        return helper(row + 1, min_bucket_count)

    return helper(0, 0)
