import math

def max_fill(grid, capacity):
    def helper(grid, capacity, row, col, n, m):
        if row >= n:
            return 0
        if col >= m:
            return helper(grid, capacity, row + 1, 0, n, m)
        if grid[row][col] == 0:
            return helper(grid, capacity, row, col + 1, n, m)
        if capacity == 1:
            return 1 + helper(grid, capacity, row, col + 1, n, m)
        return 1 + helper(grid, capacity - 1, row, col + 1, n, m)

    n = len(grid)
    m = len(grid[0])
    return helper(grid, capacity, 0, 0, n, m)
