def even_odd_count(num):
    even = 0
    odd = 0
    while num > 0:
        digit = num % 10
        if digit % 2 == 0:
            even += 1
        else:
            odd += 1
        num //= 10
    if (num > 0) and (num % 2 == 0):
        even += 1
    elif (num > 0) and (num % 2 != 0):
        odd += 1
    return (even, odd)

