def hex_key(num):
    def is_prime(n):
        """Check if a number is prime."""
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def digit_to_prime(digit):
        """Map a hexadecimal digit to a prime number if exists."""
        prime_map = {"2": 2, "3": 3, "5": 5, "7": 7, "B": 11, "D": 13}
        return prime_map.get(digit)

    count = 0
    for digit in num.upper():
        count += 1 if is_prime(digit_to_prime(digit)) else 0

    return count
