import re

def hex_key(num):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    prime_digits = '235BD'
    count = 0
    for char in num:
        if char == 'A' or char == 'B' or char == 'C' or char == 'D' or char == 'E' or char == 'F':
            if char in prime_digits:
                count += 1
        elif char in '0123456789':
            if is_prime(int(char)):
                count += 1

    if not re.match(r'^[0-9A-F]+$', num):
        return 0

    return count
