def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    def replace_vowel(c):
        if c.isalpha():
            if c.islower():
                if ord(c) - 97 < 20:
                    return chr(ord(c) - 97 + 22)
                else:
                    return c
            else:
                if ord(c) - 65 < 20:
                    return chr(ord(c) - 65 + 22)
                else:
                    return c

    return ''.join(replace_vowel(c) for c in message if c.isalpha() or c.isspace())
