    can_arrange([1,2,4,3,5]) = 3
    can_arrange([1,2,3]) = -1
    """
    if not arr:
        return -1

    max_index = -1
    for i in range(1, len(arr)):
        if arr[i-1] >= arr[i]:
            current_index = i - 1
            latest_less = -1
            for j in range(i, len(arr)):
                if arr[j] < arr[j-1]:
                    latest_less = j - 1
                    break
                elif arr[j] > arr[j-1]:
                    break
                if current_index < latest_less:
                    latest_less = current_index
                    current_index = i
            if latest_less == -1:
                max_index = current_index
            else:
                max_index = current_index
    for i in range(1, len(arr)):
       if arr[i-1]>arr[i]:
        harietto = i
    if harietto != max(max_index, max(harietto)):
        return max_index
    return -1
