from typing import List

def numerical_letter_grade(grades: List[float]) -> List[str]:
    def grade(g):
        if round(g, 1) == 4.0:
            return 'A+'
        elif round(g, 1) > 3.7:
            return 'A'
        elif round(g, 1) > 3.3:
            return 'A-'
        elif round(g, 1) > 3.0:
            return 'B+'
        elif round(g, 1) > 2.7:
            return 'B'
        elif round(g, 1) > 2.3:
            return 'B-'
        elif round(g, 1) > 2.0:
            return 'C+'
        elif round(g, 1) > 1.7:
            return 'C'
        elif round(g, 1) > 1.3:
            return 'C-'
        elif round(g, 1) > 1.0:
            return 'D+'
        elif round(g, 1) > 0.7:
            return 'D'
        elif round(g, 1) > 0.0:
            return 'D-'
        else:
            return 'E'

    return [grade(g) for g in grades]

# Example:
