def numerical_letter_grade(grades):
    grade_equations = {
        (4.0, 'A+'): '', ('3.7', 'A'), ('3.3', 'A-'), ('3.0', 'B+'), ('2.7', 'B'),
        ('2.3', 'B-'), ('2.0', 'C+'), ('1.7', 'C'), ('1.3', 'C-'), ('1.0', 'D+'),
        ('0.7', 'D'), ('0.0', 'D-'), ('0.0', 'E')
    }
    return [get_letter_grade(gpa) for gpa in grades]

def get_letter_grade(gpa):
    for tuple in sorted(grade_equations.keys(), reverse=True):
        if gpa >= tuple[0]:
            return tuple[1]
    return None
