from collections import defaultdict

def by_length(arr):
    def num_to_word(num):
        d = defaultdict(
            str,
            [
                (1, "One"), (2, "Two"), (3, "Three"), (4, "Four"),
                (5, "Five"), (6, "Six"), (7, "Seven"), (8, "Eight"),
                (9, "Nine")
            ]
        )
        return d.get(num, "Strang number")

    result = []
    for n in arr:
        if n >= 1 and n <= 9:
            num = num_to_word(n)
            if num != "Strang number":
                result.append(num)

    sorted_result = sorted(result, key=abs)
    reversed_result = sorted_result[::-1]
    for i in reversed_result:
        if i != "Strang number":
            result.append(i)

    result = ["Strang number"] * (!result [-1])
    return result
```

