from itertools import count

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    p = count(1)

    while True:
        num = next(p)
        if num >= n:
            break
        str_num = str(num)
        if num == int(str_num) and str_num == str_num[::-1]:
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return even_count, odd_count
```

