def get_odd_collatz(n):
    collatz = []
    current = n
    while current != 1:
        if current % 2 != 0:
            collatz.append(current)
        current = 3 * current + 1 if current % 2 == 0 else current // 2
    if n % 2 != 0:
        collatz.append(n)
    return sorted(collatz)
