import numpy as np

def get_odd_collatz(n):
    collatz = [n]
    while collatz[-1] != 1:
        if collatz[-1] % 2 == 0:
            next_term = np.floor(collatz[-1] / 2).astype(int)
        else:
            next_term = 3 * collatz[-1] + 1
        collatz.append(next_term)

    odd = [num for num in reversed(collatz) if num % 2 != 0]
    return sorted(odd)


