from collections import deque

def match_parens(lst):
    def is_valid(s):
        stack = deque()
        for c in s:
            if c == '(':
                stack.append(c)
            elif c == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    return 'Yes' if is_valid(''.join(lst)) else 'No'
```

