from itertools import permutations

def match_parens(lst):
    def is_good(s):
        stack = []
        for c in s:
            if c == '(':
                stack.append(c)
            elif c == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    for p in permutations(lst):
        if is_good(''.join(p)) and is_good(''.join(reversed(p))):
            return 'Yes'
    return 'No'
