def prod_signs(arr):
    if not arr:
        return None

    sign = 1
    magnitude_sum = 0
    for num in arr:
        if num > 0:
            magnitude_sum += abs(num)
            sign *= 1
        elif num < 0:
            magnitude_sum += abs(num)
            sign *= -1
        else:
            magnitude_sum += abs(num)

    return sign * magnitude_sum
```

