import math

def modp(n: int, p: int):
    def powmod(a: int, b: int, p: int):
        """Return a^b modulo p."""
        result = 1
        a = a % p
        while b > 0:
            if b % 2 == 1:
                result = (result * a) % p
            b = b // 2
            a = (a * a) % p
        return result

    return powmod(n, p - 1, p)
