import math

def words_in_sentence(sentence):
    """
    Find words with prime lengths in a sentence.

    Args:
    sentence (str): Input sentence containing words separated by spaces.

    Returns:
    str: A string of words with prime lengths from the original sentence.

    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        max_div = math.floor(math.sqrt(n))
        for i in range(3, 1 + max_div, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result = [word for word in words if is_prime(len(word))]
    return ' '.join(result)

