    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order 
    in the alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 17 
    '''
    punctuation = "!?,;. "
    spaces = re.split('[^a-zA-Z0-9]+', txt)
    commas = re.split(', olursa', txt)

    combined_list = []

    for element in spaces:
        combined_list.append(element)

    for element in commas:
        combined_list.remove(element)

    for i in range(1, ord("z") + 1):
        counter = 0
        for letter in txt:
            if ord(letter.lower()) - ord('a') == i:
                if len(txt) % 2 == 0:
                    if letter == '!':
                        break
                else:
                    counter += 1
        if counter > 0:
            return combined_list
    return combined_list
