def tri(n):
    def tribonacci(num, memo={}):
        if num in memo:
            return memo[num]
        if num == 1:
            return 3
        elif num % 2 == 0:
            return 1 + (num // 2)
        else:
            result = tribonacci(num - 1, memo) + tribonacci(num - 2, memo) + tribonacci(num + 1, memo)
            memo[num] = result
            return result

    return [tribonacci(i) for i in range(n + 1)]

# Example usage:
