def count_nums(arr):
    def has_positive_digit(num):
        return any(digit > 0 for digit in str(abs(num)))

    def get_first_significant_digit(num):
        if num < 0:
            return -int(str(abs(num))[0])
        else:
            return int(str(abs(num))[0])

    def sum_of_digits(num):
        return sum(int(digit) for digit in str(abs(num)))

    return sum(1 for num in arr if has_positive_digit(num) or sum_of_digits(num) > 0 and get_first_significant_digit(num) > 0)
