import heapq

def next_smallest(lst):
    """
    You are given a list of integers.
    Writes a function next_smallest() that returns the 2nd smallest element of the list.
    Return None if there is no such element.

    next_smallest([1, 2, 3, 4, 5]) == 2
    next_smallest([5, 1, 4, 3, 2]) == 2
    next_smallest([]) == None
    next_smallest([1, 1]) == None
    """
    if len(lst) == 0 or len(lst) == 1:
        return None

    freq = {}
    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    max_heap = []
    for key in freq:
        heapq.heappush(max_heap, (-freq[key], key))

    second_smallest = None
    while len(max_heap) > 1:
        freq1, key1 = heapq.heappop(max_heap)
        freq2, key2 = heapq.heappop(max_heap)
        if second_smallest is None:
            second_smallest = -freq1 + key1
        else:
            second_smallest = min(second_smallest, -freq1 + key1)

    return second_smallest
```

