def match_parens(lst):
    """
    Return the complete function (including the imports and signature) in a single code block, with no explanation.

    Args:
        lst (list): A list of two strings, each containing only open or close parentheses.

    Returns:
        str: 'Yes' if there's a way to make a good string, 'No' otherwise.
    """
    def isValid(string):
        stack = []
        for char in string:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    open_parens = 0
    close_parens = 0

    for string in lst:
        if string.count('(') == string.count(')'):
            if isValid(string):
                return 'Yes'
        elif string.count('(') > string.count(')'):
            open_parens = string.count('(')
            close_parens = string.count(')')
            if open_parens < close_parens * 2:
                return 'Yes'
    return 'No'

