import math

def max_fill(grid, capacity):
    def count_bucket(filename, capacity):
        buckets = 0
        water = 0
        for row in grid:
            water += row.count(1)
            buckets += (water + capacity - 1) // capacity
        return buckets

    def count_bucket_with_proportion(filename, capacity):
        buckets = 0
        water = 0
        for row in grid:
            water += row.count(1)
            if water >= capacity:
                buckets += 1
                water -= capacity
            else:
                buckets += water // capacity
                water %= capacity
        return buckets

    def count_bucket_with_threshold(filename, capacity):
        buckets = 0
        water = 0
        for row in grid:
            water += row.count(1)
            if water >= capacity:
                buckets += 1
            else:
                buckets += water // capacity
                water %= capacity
        return buckets

    def count_bucket_with_loop(filename, capacity):
        buckets = 0
        for row in grid:
            water = row.count(1)
            buckets += (water + capacity - 1) // capacity
        return buckets

    def count_bucket_with_counter(filename, capacity):
        buckets = 0
        water = 0
        counter = 0
        for row in zip(*grid):
            water += sum(row)
            buckets += (water + capacity - 1) // capacity
            counter += 1
        return buckets

    def count_bucket_with_reduce(filename, capacity):
        buckets = 0
        water = 0
        for row in zip(*grid):
            water += sum(row)
            buckets += (water + capacity - 1) // capacity
        return buckets

    return count_bucket(grid, capacity)
