from functools import lru_cache

def fib(n: int):
    """Return n-th Fibonacci number.
    >>> fib(10)
    55
    >>> fib(1)
    1
    >>> fib(8)
    21
    """
    @lru_cache(maxsize=None)
    def fib_helper(x: int):
        if x < 2:
            return x
        return fib_helper(x-1) + fib_helper(x-2)
    return fib_helper(n)
