def rounded_avg(n, m):
    if n > m:
        return -1

    if n < m:
        sum_ = sum(range(n, m + 1))
    else:
        sum_ = m * (m - n + 1) // 2

    avg = sum_ // (m - n + 1)
    avg_bin = bin(avg)[2:]

    return '0b' + avg_bin.ljust(m - n + 1, '0')

