def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shifted_alphabet = alphabet[2:] + alphabet[:2]
    result = ''
    for char in s:
        if char.isalpha():
            if char.isupper():
                result += shifted_alphabet[(alphabet.index(char.lower()) + 2) % 26].upper()
            else:
                result += shifted_alphabet[alphabet.index(char) + 2]
        else:
            result += char
    return result
