from string import ascii_uppercase, ascii_lowercase

def Strongest_Extension(class_name, extensions):
    def strength(extension):
        return sum(1 for char in extension if char in ascii_uppercase) - sum(1 for char in extension if char in ascii_lowercase)

    strongest = extensions[0]
    max_strength = strength(strongest)
    for extension in extensions[1:]:
        extension_strength = strength(extension)
        if extension_strength > max_strength:
            strongest = extension
            max_strength = extension_strength

    return f"{class_name}.{strongest}"
