from string import ascii_letters

def Strongest_Extension(class_name, extensions):
    def calculate_strength(extension):
        return sum(1 for char in extension if char.isupper()) - sum(1 for char in extension if char.islower())

    strongest_extension = extensions[0]
    max_strength = calculate_strength(strongest_extension)

    for extension in extensions[1:]:
        strength = calculate_strength(extension)
        if strength > max_strength:
            max_strength = strength
            strongest_extension = extension

    return f"{class_name}.{strongest_extension}"
```

```python
from typing import List

def Strongest_Extension(class_name: str, extensions: List[str]) -> str:
    def strength(extension: str) -> float:
        return sum(1 for char in extension if char.isupper()) - sum(1 for char in extension if char.islower())

    strongest = extensions[0]
    max_strength = strength(strongest)

    for extension in extensions[1:]:
        if strength(extension) == max_strength:
            strongest = extension
        elif strength(extension) > max_strength:
            strongest = extension
            max_strength = strength(extension)

    return f"{class_name}.{strongest}"
```

