def get_closest_vowel(word):
    def is_vowel(char):
        return char.lower() in 'aeiou'

    def is_consonant(char):
        return char.isalpha() and char.lower() not in 'aeiou'

    vowels = [char for char in word if is_vowel(char)]
    consonants = [char for char in word if is_consonant(char)]

    if len(consonants) < 2:
        return ""

    for i in range(len(consonants) - 1, 0, -1):
        if is_vowel(consonants[i]):
            return consonants[i - 1] + vowels[0]

    return ""

