def move_one_ball(arr):
    if len(arr) == 0:
        return True

    min_index = arr.index(min(arr))

    if min_index == len(arr) - 1:
        return True

    for i in range(min_index, len(arr) - 1):
        if arr[i] > arr[i + 1]:
            return False

    return True
