from typing import List

def move_one_ball(arr: List[int]) -> bool:
    if not arr:
        return True

    min_val = arr[0]
    min_index = 0

    for i in range(1, len(arr)):
        if arr[i] < min_val:
            min_val = arr[i]
            min_index = i

    return arr[-1] <= min_val
```

```python
from typing import Dict

def count_distinct_characters(string: str) -> int:
    """ Given a string, find out how many distinct characters (regardless of case) does it consist of
    >>> count_distinct_characters('xyzXYZ')
    3
    >>> count_distinct_characters('Jerry')
    4
    """
    cache: Dict[str, set] = {}  # to store distinct characters at different prefix lengths.
    def helper(s: str) -> int:
        if not s: 
            return 0
        if s in cache: 
            return len(cache[s]) # if string already calculated.
        else:
            distinct: set = set(s[0])
            for i in range(1, len(s)):
                distinct = distinct.union(set(s[i]))
            cache[s] = distinct
            return len(distinct) + helper(s[1:])  # recurse for the rest of string
    return helper(string)
```

