from collections import defaultdict

def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    max_triples = 0
    counter = defaultdict(int)
    for i in range(n):
        num = a[i]
        for j in range(i + 1, n):
            k = a[j]
            if (num + k + a[j + 1] if j + 1 < n else k + num) % 3 == 0:
                triple = tuple(sorted([num, k, a[j + 1] if j + 1 < n else k + num]))
                if triple not in counter:
                    counter[triple] = 1
                else:
                    counter[triple] += 1
                max_triples = max(max_triples, counter[triple])
        counter.clear()
    return max_triples
```

