    max_triples = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            for k in range(j + 1, len(arr)):
                if (arr[i] + arr[j] + arr[k]) % 3 == 0 and i < j < k:
                    max_triples += 1
    return max_triples
