import re

def file_name_check(file_name):
    if len(file_name) < 0:
        return 'No'

    if re.search(r'\d', file_name) and len(re.findall(r'\d', file_name)) > 3:
        return 'No'

    if re.sub(r'\.', '', file_name).strip() == '':
        return 'No'

    if not re.match('^[a-zA-Z]', re.sub(r'\.', '', file_name).strip().lower()):
        return 'No'

    if not set(re.sub(r'\.', '', file_name).strip().lower()).issubset(set(['txt', 'exe', 'dll'])):
        return 'No'

    return 'Yes'
```

