def count_nums(arr):
    def has_significant_digits(num):
        sig_digit = num if num < 0 else -abs(num)
        while not sig_digit:
            num //= 10
            if num < 0:
                sig_digit = -abs(num)
            else:
                sig_digit = abs(num)
        return sig_digit > 0
    return sum(has_significant_digits(num) for num in arr)
```

