def generate_integers(a, b):
    """
    Given two positive integers a and b, return the even digits between a
    and b, in ascending order.

    For example:
    generate_integers(2, 8) => [2, 4, 6, 8]
    generate_integers(8, 2) => [2, 4, 6, 8]
    generate_integers(10, 14) => []
    """
    def is_even(n):
        if isinstance(n, int):
            return n % 2 == 0
        else:
            raise TypeError("Input must be integers.")

    def is_digit(n, d):
        if isinstance(d, int):
            return d >= 0 and d <= 9
        else:
            raise TypeError("Digit must be between 0 and 9.")

    debugging_info = []

    def helper(x):
        if x < min(a, b):
            return
        if not is_even(x):
            return
        if x >= max(a, b):
            return
        debugging_info.append(x)
        if x < max(a, b):
            helper(x + 1)

    helper(a)
    result = debugging_info[1:-1]
    return result if result else []
