import math

def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    for i in range(2, a):
        for j in range(2, a):
            for k in range(2, a):
                if i * j * k == a and is_prime(i) and is_prime(j) and is_prime(k):
                    return True
    return False
```

