def max_fill(grid, capacity):
    import math
    rows, cols = len(grid), len(grid[0])
    steps = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                steps += (cols - j)
                if steps % capacity == 0:
                    steps += capacity
    return steps
