def max_fill(grid, capacity):
    import math

    def count_wells(grid, bucket_capacity):
        count = 0
        for row in grid:
            for well in row:
                if well == 1:
                    count += bucket_capacity - (bucket_capacity - 1) % well
        return count

    return count_wells(grid, capacity)
