from collections import deque

def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    num_values = set([val for row in grid for val in row])

    # find the starting point
    for i in range(n):
        for j in range(n):
            if grid[i][j] in num_values:
                start = (i, j)
                break

    queue = deque([(start, [start[0], start[1]])])
    visited = set([start])

    while queue:
        (x, y), path = queue.popleft()
        if len(path) == k:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                queue.append(((nx, ny), path + [nx, ny]))
                visited.add((nx, ny))

    return []
```

