from collections import deque

def minPath(grid, k):
    n = len(grid)
    res = []
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                res, visited = bfs(grid, k, i, j, res)
                if len(res) == k:
                    return res
    return []

def bfs(grid, k, i, j, res):
    queue = deque([(i, j, 1)])
    visited = set((i, j))
    while queue:
        curr_i, curr_j, curr_val = queue.popleft()
        if curr_val == k:
            res.extend([grid[curr_i][curr_j]] * k)
            return res, len(res)
        for ni, nj in [(curr_i-1, curr_j), (curr_i+1, curr_j), (curr_i, curr_j-1), (curr_i, curr_j+1)]:
            if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]) and (ni, nj) not in visited:
                queue.append((ni, nj, curr_val + 1))
                visited.add((ni, nj))
    return [], 0

