from collections import deque

def minPath(grid, k):
    n = len(grid)
    paths = []
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                paths.append([grid[i][j]])
                queue = deque([(i, j, 1)])
                visited = {(i, j)}
                while queue:
                    x, y, dist = queue.popleft()
                    if dist == k:
                        paths[-1].extend(grid[x][y:x+1])
                        break
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                            queue.append((nx, ny, dist + 1))
                            visited.add((nx, ny))
    return min(paths, key=lambda x: x)

# Test the function
print(minPath([[1,2,3], [4,5,6], [7,8,9]], 3))  # [1, 2, 1]
print(minPath([[5,9,3], [4,1,6], [7,8,2]], 1))  # [1]
