def get_closest_vowel(word):
    vowels = 'aeiouAEIOU'
    closest = ''
    for i in range(len(word) - 1, -1, -1):
        if word[i] in vowels:
            closest = word[i]
            break
        if word[i].isalpha():
            closest = min([v for v in vowels if (i < len(word) - 1 and word[i + 1] in vowels)], key=lambda v: abs(ord(v) - ord(word[i])), default='')
    return closest
```

