import re

def get_closest_vowel(word):
    vowels = 'AEIOU'
    word = word.upper()
    prev_vowel = re.search(r'[AEIOU]', str(word)[-2])
    if prev_vowel is None:
        return ""
    index = prev_vowel.start()
    prev_char = word[index]
    if prev_char not in vowels:
        index -= 1
    while index > 0 and word[index] not in vowels and word[index - 1] not in vowels:
        index -= 1
    while index < len(word) - 1 and word[index] not in vowels and word[index + 1] not in vowels:
        index += 1
    if index > 0 and index < len(word) - 1:
        return word[index]
    elif index == 0:
        return word[index.row[-2]]
    else:
        return ""
```

