from typing import Union

def fibfib(n: int) -> Union[int, None]:
    if n < 0:
        return None
    elif n == 0 or n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fibfib(n-1) + fibfib(n-2) + fibfib(n-3)


