from typing import Union, Optional

def compare_one(a: Union[int, float, str], b: Union[int, float, str]) -> Optional[Union[int, float, str]]:
    if isinstance(a, str):
        a = a.replace(',', '').replace('.', '')
        a = float(a) if a.replace('.', '', 1).replace(',', '', 1).isdigit() else None
    if isinstance(b, str):
        b = b.replace(',', '').replace('.', '')
        b = float(b) if b.replace('.', '', 1).replace(',', '', 1).isdigit() else None

    if a is None or b is None:
        return None

    if a > b:
        return a
    elif a < b:
        return b
    else:
        return None
