from decimal import Decimal

def compare_one(a, b):
    if isinstance(a, str) and isinstance(b, str):
        a = a.replace(',', '').replace('.', '')
        b = b.replace(',', '').replace('.', '')
        if Decimal(a) > Decimal(b):
