        return "NO"

    intersection_start = max(interval1[0], interval2[0])
    intersection_end = min(interval1[1], interval2[1])

    if intersection_start == end:
        if is_prime(max(0, end - intersection_start + 1)):
            return "YES"
        else:
            return "NO"

    return "NO"


