from decimal import Decimal

def compare_one(a, b):
    def convert_and_compare(x):
        if isinstance(x, str):
            try:
                return max(replace_comma(x), float(x))
            except ValueError:
                return x
        elif isinstance(x, float):
            return x
        else:
            try:
                return float(x)
            except ValueError:
                return None

    def replace_comma(x):
        x = str(x).replace(',', '')
        if '.' in x and x.split('.')[0].isdigit():
            return Decimal(x)
        elif x.isdigit():
            return float(x)
        else:
            return None

    return convert_and_compare(a) if a > b else convert_and_compare(b) if b > a else None
