def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers
    Example
    is_equal_to_sum_even(4) == False
    is_equal_to_sum_even(6) == False
    is_equal_to_sum_even(8) == True
    """
    def is_even(num):
        return num % 2 == 0

    def is_sum_of_four_even(num):
        for i in range(2, num // 2 + 1):
            if num % i == 0:
                for j in range(i, (num // i) // 2 + 1):
                    if num % j == 0:
                        for k in range(j, (num // j) // 2 + 1):
                            if num % k == 0:
                                for m in range(k, (num // k) // 2 + 1):
                                    if num % m == 0 and is_even(i) and is_even(j) and is_even(k) and is_even(m):
                                        return True
        return False

    return is_sum_of_four_even(n)
