        sequence = [num]
        while num != 1:
            if num % 2 == 0:
                num = num // 2
            else:
                num = 3 * num + 1
            sequence.append(num)
        return sequence

    return sorted([num for num in range(1, n+1) if collatz(num) % 2 != 0])
