    if len(arr) == 0:
        return True

    is_sorted = True
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            is_sorted = False
            break

    if is_sorted:
        return True

    min_index = arr.index(min(arr))

    if min_index == 0:
        return True

    return False
