import math

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    def count_numbers(digit_length, start_end):
        if digit_length == 0:
            return 1 if start_end else 0
        elif digit_length == 1:
            return start_end
        else:
            return 9 * count_numbers(digit_length - 1, False) + count_numbers(digit_length - 1, True)

    return count_numbers(n, True)
```

