```python
def encode(message):
    """
    This function encodes a given message by swapping the case of all letters and replacing 
    all vowels with the letter that appears 2 places ahead of that vowel in the english alphabet.

    Parameters:
    message (str): The input message to be encoded.

    Returns:
    str: The encoded message.
    """
    encoded = ""
    for char in message:
        if char == 'a' or char == 'A':
            encoded += 'b'
        elif char == 'e' or char == 'E':
            encoded += 'f'
        elif char == 'i' or char == 'I':
            encoded += 'j'
        elif char == 'o' or char == 'O':
            encoded += 'p'
        elif char == 'u' or char == 'U':
            encoded += 'v'
        else:
            if char.islower():
                encoded += char.lower()
            else:
                encoded += char.upper()
    return encoded
```

