def encode(message):
    vowels = 'aeiouAEIOU'
    new_message = ''

    for char in message:
        if char in vowels:
            index = ((ord(char) - 97) + 2) % 26
            new_char = chr(index + 97)
        else:
            new_char = char

        if char.isupper():
            new_char = new_char.upper()

        new_message += new_char

    return new_message
```

