from collections import Counter

def reverse_delete(s, c):
    s_count = Counter(s)
    c_count = Counter(c)
    for char, count in c_count.items():
        if char in s_count:
            s_count[char] -= count
    if s_count == Counter(s):
        return s, True
    else:
        return ''.join([char for char, count in s_count.items() if count > 0]), False
