from functools import cmp_to_key

def Strongest_Extension(class_name, extensions):
    def strength(a, b):
        cap_a, sm_a = a.count('A') - a.count('a'), a.count('a') - a.count('A')
        cap_b, sm_b = b.count('A') - b.count('a'), b.count('a') - b.count('A')
        return (cap_b - sm_b) - (cap_a - sm_a)

    best_extension = extensions[0]
    for extension in extensions[1:]:
        if strength(extension, best_extension) > 0:
            best_extension = extension

    return f"{class_name}.{best_extension}"
