def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shift = 2
    result = ''

    for char in s:
        if char.isalpha():
            if char.islower():
                pos = alphabet.index(char)
                result += alphabet[(pos + shift) % 26]
            else:
                pos = alphabet.index(char.lower())
                result += alphabet[(pos + shift) % 26].upper()
        else:
            result += char

    return result
```

