def encrypt(s):
    alphabet = 'abcdefghilmnopqrstuvwxyz'
    result = ''
    for char in s:
        if char.isalpha():
            shift = alphabet.index(char.lower()) + 2
            if char.isupper():
                result += alphabet[shift % 26].upper()
            else:
                result += alphabet[shift % 26]
        else:
            result += char
    return result
