    prev = arr[0]
    max_index = 0

    for i in range(1, len(arr)):
        if arr[i] >= prev:
            max_index = i
        else:
            break

    if arr[-1] <= prev:
        max_index = len(arr) - 1

    return max_index if max_index != len(arr) else -1
