from math import floor, ceil

def closest_integer(value):
    if "." in value:
        num = int(value.split(".")[0]) + float(value.split(".")[1])
    else:
        num = int(value)

    if num - floor(num) == 0.5:
        if (floor(num) + 1) >= 0 and floor(num) + 1 >= -num:
            return num + 1
        else:
            return num
    else:
        if num % 1 != 0:
            return int(num) + (num - int(num))
        else:
            return int(num)

print(closest_integer("10"))  # 10
print(closest_integer("15.3")) # 15
print(closest_integer("14.5")) # 15
print(closest_integer("-14.5")) # -15
```

