import math

def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    factors = []
    for i in range(2, a + 1):
        while a % i == 0:
            factors.append(i)
            a //= i
    if len(factors) < 3:
        return False
    for i in range(2, len(factors)):
        if not is_prime(factors[i]):
            return False
    return len(factors) == 3
```

