from functools import lru_cache

def tri(n):
    @lru_cache(maxsize=None)
    def helper(n):
        if n == 1:
            return 3
        if n % 2 == 0:
            return 1 + n // 2
        return helper(n - 1) + helper(n - 2) + helper(n + 1)

    return [helper(i) for i in range(n + 1)]
```

