from collections import deque

def tri(n):
    if n < 1:
        return []
    elif n == 1:
        return [3]
    elif n == 2:
        return [1, 3]
    else:
        result = [3, 1, 3]
        tribonacci = deque([3, 1, 3])
        for _ in range(2, n):
            next_tribonacci = tribonacci[0] + tribonacci[1] + tribonacci[2]
            tribonacci.appendleft(next_tribonacci - tribonacci[0])
            result.append(next_tribonacci)
        return result
