from collections import deque

def get_row(lst, x):
    result = []
    queue = deque()

    for i, row in enumerate(lst):
        if x in row:
            queue.append((i, row.index(x)))

    while queue:
        row, col = queue.popleft()
        result.append((row, col))
        if row > 0 and len(lst[row - 1]) > col:
            queue.appendleft((row - 1, col))
        if row < len(lst) - 1 and len(lst[row + 1]) > col:
            queue.append((row + 1, col))
        if row > 0 and len(lst[row - 1]) > col + 1:
            queue.appendleft((row - 1, col + 1))
        if row < len(lst) - 1 and len(lst[row + 1]) > col + 1:
            queue.append((row + 1, col + 1))

    # Sort by rows in ascending order
    result.sort(key=lambda x: x[0])

    # Sort by columns in descending order
    result.sort(key=lambda x: (-x[1], x[0]))

    return result
```

