import math

def intersection(interval1, interval2):
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        sqrt_n = math.sqrt(n)
        for i in range(3, int(sqrt_n) + 1, 2):
            if n % i == 0:
                return False
        return True

    if max(interval1[0], interval2[0]) < min(interval1[1], interval2[1]):
        return "NO"
    intersection_start = max(interval1[0], interval2[0])
    intersection_end = min(interval1[1], interval2[1])
    intersection_length = intersection_end - intersection_start
    if is_prime(intersection_length):
        return "YES"
    else:
        return "NO"

