from datetime import datetime

def valid_date(date_str):
    if not date_str:
        return False

    try:
        date = datetime.strptime(date_str, '%m-%d-%Y')
    except ValueError:
        return False

    month = date.month
    day = date.day

    if month in [1, 3, 5, 7, 8, 10, 12] and day > 31:
        return False

    if month in [4, 6, 9, 11] and day > 30:
        return False

    if month == 2 and (day > 29 or (day == 29 and not (date.year % 4 == 0 and (date.year % 100 != 0 or date.year % 400 == 0))))):
        return False

    if month < 1 or month > 12:
        return False

    return True
