from datetime import datetime

def valid_date(date):
    if not date:
        return False

    try:
        date_obj = datetime.strptime(date, '%m-%d-%Y')
    except ValueError:
        return False

    month, day, year = date_obj.month, date_obj.day, date_obj.year

    if not (1 <= month <= 12):
        return False

    if month in [1, 3, 5, 7, 8, 10, 12]:
        if not (1 <= day <= 31):
            return False
    elif month in [4, 6, 9, 11]:
        if not (1 <= day <= 30):
            return False
    elif month == 2:
        if not (1 <= day <= 29):
            return False

    return True
