from typing import Tuple

def reverse_delete(s: str, c: str) -> Tuple[str, bool]:
    def is_palindrome(s: str) -> bool:
        return s == s[::-1]

    c_set = set(c)
    result = [x for x in s if x not in c_set]
    return ''.join(result), is_palindrome(''.join(result))
