def get_max_triples(n):
    arr = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0
    for i in range(len(arr)):
        for j, k in combinations(range(i + 1, len(arr)), 2):
            if (arr[i] + arr[j] + arr[k]) % 3 == 0:
                count += 1
    return count
```

