from typing import List

def parse_music(music_string: str) -> List[int]:
    result = []
    factor = 1

    for char in music_string:
        if char == 'o':
            result.append(factor * 4)
        elif char == '|':
            result.append(factor * 2)
            factor = 0.5
        elif char == '.':

            result.append(factor * 1)
            factor = 0.25
        elif char == ' ':
            factor = 1

    return result
