from math import factorial

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    def n_digit_numbers(n):
        return 9 * factorial(n - 1)

    def n_digit_numbers_starting_with_one(n):
        return 9 * (factorial(n - 1) - factorial(n - 2))

    def n_digit_numbers_ending_with_one(n):
        return 9 * (factorial(n - 1) - factorial(n - 2))

    def n_digit_numbers_starting_and_ending_with_one(n):
        return 9 * (factorial(n - 1) - factorial(n - 2))

    return n_digit_numbers(n) - n_digit_numbers_starting_with_one(n) - n_digit_numbers_ending_with_one(n) + n_digit_numbers_starting_and_ending_with_one(n)
```

