def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    def count_numbers(length, start=0, end=0):
        if length == 0:
            return 1
        count = 0
        for i in range(10):
            if (start == 0 or i == 1) and (end == 0 or i == 1):
                count += count_numbers(length - 1, start | end, end | i)
            elif i == 1 and (start | end) == 1:
                count += count_numbers(length - 1, start | i, end | i)
            else:
                count += count_numbers(length - 1, start, end)
        return count

    return count_numbers(n)
