from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_valid(p: str):
        return p.count('(') == p.count(')')

    def separate(s: str) -> List[str]:
        if not s:
            return []
        if is_valid(s):
            return [s]
        for i in range(1, len(s)):
            left = s[:i]
            right = s[i:]
            left_group = separate(left)
            right_group = separate(right)
            if left_group and right_group:
                return [left_group[0] + right_group[0]]
        return []

    stack = []
    result = []
    for c in paren_string.replace(" ", ""):
        if c == '(':
            stack.append(c)
        elif c == ')':
            if stack:
                stack.pop()
        else:
            if stack:
                result.append(''.join(stack))
                stack = []
    if stack:
        result.append(''.join(stack))
    return result
```

