def exchange(lst1, lst2):
    queue = deque(lst)
    visited = set(lst)
    while queue:
        if queue[0] % 2 == 0:
            queue.popleft()
            continue
        temp = queue.popleft()
        queue.append(temp)
        if temp not in visited:
            visited.add(temp)
            if temp % 2 == 0:
                continue
            if lst2 and temp in lst2:
                lst2.remove(temp)
                visited.add(temp)
        if len(queue) == 0:
            return "YES"
    return "NO" if len(queue) != 0 else "NO"
