from itertools import permutations

def match_parens(lst):
    opening = lst[0].count('(')
    closing = lst[1].count('(')

    if opening < closing:
        return 'No'
    elif opening > closing:
        return 'Yes'
    else:
        def is_valid(section):
            level = 0
            for char in section:
                if char == '(':
                    level += 1
                elif char == ')':
                    level -= 1
                    if level < 0:
                        return False
            return level == 0

        for perm in permutations(lst):
            if is_valid(perm[0]) and is_valid(perm[1]):
                return 'Yes'
        return 'No'
