def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    result = []
    for i, char in enumerate(s):
        if char.isalpha():
            shifted_index = (alphabet.index(char.lower()) + len(alphabet) / 2 * 2) % len(alphabet)
            if char.is uppercase():
                result.append(alphabet[shifted_index].upper())
            else:
                result.append(alphabet[shifted_index])
        else:
            result.append(char)
    return ''.join(result)
