from string import ascii_uppercase, ascii_lowercase

def Strongest_Extension(class_name, extensions):
    cap, sm = 0, 0
    strongest = None

    for extension in extensions:
        temp_cap, temp_sm = 0, 0
        for char in extension:
            if char.isupper():
                temp_cap += 1
            elif char.islower():
                temp_sm += 1

        if temporary_strength = temp_cap - temp_sm and (strongest is None or temporary_strength > strongest['strength']):
            strongest = {
                'extension': extension,
                'strength': temporary_strength
            }
        elif temporary_strength > strongest['strength']:
            strongest = {
                'extension': extension,
                'strength': temporary_strength
            }

    shortest_extension = min(strongest['extension'], key=len)
    return f'{class_name}.{shortest_extension}'
