```python
from string import ascii_uppercase, ascii_lowercase

def Strongest_Extension(class_name, extensions):
    def strength(extension):
        cap = sum(1 for c in extension if c in ascii_uppercase)
        sm = sum(1 for c in extension if c in ascii_lowercase)
        return (cap - sm) / len(extension)

    strong_extension = max((e for e in extensions if e != class_name), key=lambda e: strength(e))
    return f"{class_name}.{strong_extension}"
```

