from collections import defaultdict

def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    max_triples = 0
    for i in range(n):
        counts = defaultdict(int)
        for j in range(i + 1, n):
            remainder = (a[i] + a[j]) % 3
            if remainder == 0:
                triples = 1
                for k in range(j + 1, n):
                    if (a[i] + a[j] + a[k]) % 3 == 0:
                        triples += 1
                        counts[a[k]] += 1
                max_triples = max(max_triples, triples)

    return max_triples
