from collections import deque

def exchange(lst1, lst2):
    queue = deque([(lst1, 0, 0)])
    visited = set(tuple(lst1))
    while queue:
        current_lst, current_step, parity = queue.popleft()
        if all(num % 2 == 0 for num in current_lst):
            if parity == 0:
                return "YES"
            else:
                return "NO"
        for i in range(len(current_lst)):
            for j in range(len(lst2)):
                new_lst1 = current_lst.copy()
                new_lst2 = lst2.copy()
                new_lst1[i], new_lst2[j] = new_lst2[j], new_lst1[i]
                new_lst = tuple(new_lst1 + new_lst2)
                if new_lst not in visited:
                    queue.append((new_lst, current_step + 1, parity ^ 1))
                    visited.add(new_lst)
    return "NO"
