from collections import defaultdict

def select_words(s, n):
    words = s.split()
    result = []
    word_count = defaultdict(int)
    max_words = defaultdict(int)
    for word in words:
        consonants = sum(1 for char in word if char.lower() not in 'aeiou')
        if consonants == n:
            if word_count[word] < 2:
                result.append(word)
            max_words[word] = max(max_words[word], word_count[word] + 1)
        word_count[word] += 1
    for key, value in max_words.items():
        while value > 1:
            result.insert(0, key)
            value -= 1
    return result
