def get_closest_vowel(word):
    def is_consonant(char):
        return char.lower() not in 'aeiou'

    def is_close_to_vowel(char, target):
        return abs(ord(char.lower()) - ord(target)) <= 1

    closest_vowel = ''
    for i in range(len(word) - 1, 0, -1):
        if is_consonant(word[i]) and is_consonant(word[i - 1]):
            for vowel in 'aeiou':
                if is_close_to_vowel(word[i - 1], vowel):
                    closest_vowel = vowel
                    break
            if closest_vowel:
                break

    return closest_vowel
```

