        return char.lower() in 'aeiou'

    closest_vowel = ''
    for i in range(len(word) - 1, 0, -1):
        if is_vowel(word[i]):
            if all(is_consonant(c) for c in word[i-1:i]):
                closest_vowel = word[i]
                break
    return closest_vowel
