from typing import Int32

def fib4(n: Int32) -> Int32:
    memory = {0: 0, 1: 0, 2: 2, 3: 0}
    while n > 3:
        fib4_n = memory[n - 1] + memory[n - 2] + memory[n - 3] + memory[n - 4]
        memory[n] = fib4_n
        n -= 1
    return memory[n]
