        self.matrix = [[0]*n for _ in range(n)]

    def normalize(self):
        self.matrix[0][0] = 1
        for k in range(self.n):
            for i in range(self.n):
                if i == 0:
                    continue
                if i == k:
                    self.matrix[i][0] = 1
                    continue
                for j in range(1, i):
