                    self.matrix[i][j] += self.matrix[i-1][j-1]
                    self.matrix[i][j] += self.matrix[i-1][j]
                    self.matrix[i][j] += self.matrix[i-1][j-1]

    def fib4(self, n: Optional[int] = None) -> int:
        if n is not None:
            if n < 0:
                raise ValueError("n must be a non-negative integer")
