def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shift = 2
    shifted_alphabet = alphabet[shift:] + alphabet[:shift]
    encrypted = ''
    for char in s:
        if char.isalpha():
            if char.islower():
                position = (alphabet.index(char) + shift) % 26
                encrypted += shifted_alphabet[position]
            else:
                position = (alphabet.index(char.lower()) + shift) % 26
                encrypted += shifted_alphabet[position].upper()
        else:
            encrypted += char
    return encrypted
```

