        return True

    def find_longest_palindromic_suffix(s: str, i: int) -> int:
        for j in range(len(s) - 1, i - 1, -1):
            if match(s, i, j):
                i = j + 1
            else:
                return i

    i = 0
    j = len(string)
    while i < j:
        if not match(string, i, j - 1):
            i += 1
        else:
            j -= 1
    # The actual palindrome found in string is from i to j
    return string[:i] + string[:i-1][::-1] + string[i:j]

