def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiou'
    encoded_message = ''
    for char in message:
        if char.isalpha():
            if char.islower():
                if char in vowels:
                    if ord(char) + 2 > ord('z'):
                        encoded_message += chr(ord('a') + (ord(char) + 2 - ord('a')) % 26)
                    else:
                        encoded_message += chr(ord(char) + 2)
                else:
                    encoded_message += char
            elif char.isupper():
                if char in vowels:
                    if ord(char) + 2 > ord('Z'):
                        encoded_message += chr(ord('A') + (ord(char) + 2 - ord('A')) % 26)
                    else:
                        encoded_message += chr(ord(char) + 2)
                else:
                    encoded_message += char
            else:
                encoded_message += char
        else:
            encoded_message += char
    return encoded_message
