from typing import Tuple

def bf(planet1: str, planet2: str) -> Tuple[str]:
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    lookup = {"Mercury": 0, "Venus": 1, "Earth": 2, "Mars": 3, "Jupiter": 4, 
             "Saturn": 5, "Uranus": 6, "Neptune": 7}

    def inner(planet1: str, planet2: str) -> Tuple[str]:
        if planet1 not in lookup or planet2 not in lookup:
            return ()

        i1, i2 = lookup[planet1], lookup[planet2]
        planets_in_range = [planet for planet in planets if i1 < lookup[planet] < i2]
        return tuple(sorted(planets_in_range))

    return inner(planet1, planet2)

