from math import pow

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    def digits(n):
        return len(str(n))

    def count_with_digits(start, end):
        if start == end:
            return 1
        if start * pow(10, n-1) > end:
            return 0
        else:
            return (end - start + 1) * (count_with_digits(start * pow(10, n-1), end) +
                                        count_with_digits(start * pow(10, n-1), end - 1))

    n_digits = digits(n)
    return count_with_digits(1, 10 ** n - 1)
