import math

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    def count_digits(num_bytes, min_length, max_length, min_digit, max_digit):
        if num_bytes == 1:
            return int(max(min_digit, max_digit) == 1)
        else:
            middle = int(math.pow(10, num_bytes - 2))
            return (count_digits(num_bytes - 1, min_length, min_digit, middle) +
                    count_digits(num_bytes - 1, max_length, middle, max_digit))

    count = 0
    for i in range(1, 10 ** n):
        count += count_digits(n, i, i, 1, 9)

    # sum the numbers of five and six digit n integers that start or end with 1
    for i in range(10**n, 10**(n+1)-1):
        count += count_digits(n, i, i, 1, 9)
    return count
