from collections import deque

def fib4(n: int):
    if n < 0:
        raise ValueError('n must be non-negative')
    fib4_sequence = deque([0, 0, 2])
    for _ in range(n - 2):
        fib4_sequence.appendleft(fib4_sequence[-1] + fib4_sequence[-2] + fib4_sequence[-3] + fib4_sequence[-4])
    return fib4_sequence[0]
