def make_palindrome(string: str) -> str:
    def is_palindrome_prefix(prefix: str) -> bool:
        return prefix == prefix[::-1]

    def longest_palindromic_prefix(s: str) -> int:
        for i in range(len(s), 0, -1):
            if is_palindrome_prefix(s[:i]):
                return i

    if len(string) == 0:
        return string
    else:
        prefix = string[:longest_palindromic_prefix(string)]
        suffix = string[longest_palindromic_prefix(string):][::-1]
        return prefix + suffix
