def is_nested(string):
    opening = 0
    closing = 0
    for bracket in string:
        if bracket == '[':
            opening += 1
        elif bracket == ']':
            closing += 1
        if closing > opening:
            return True
    return False
```

```python
def is_nested(string):
    stack = []
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if not stack:
                return False
            stack.pop()
    return bool(stack)
```

