from collections import Counter

def find_max(words):
    def unique_chars(word):
        return len(Counter(word))

    max_len = 0
    max_word = ""
    for word in words:
        if unique_chars(word) > max_len or (unique_chars(word) == max_len and word < max_word):
            max_len = unique_chars(word)
            max_word = word
    return max_word
