def split_words(txt):
    txt = txt.replace('!', '').replace('?', '').replace('.', '').replace(',', ' ')
    words = txt.split()
    if ',' in txt:
        words = txt.split(',')
    elif len(set(c for c in txt.lower() if c.isalpha())) == 25:
        return len([c for c in txt.lower() if c in 'abcdefghijkmnpqrstuvwxyz' and ord(c) % 2 != 0])
