def count_nums(arr):
    def sum_digits(n):
        sign = -1 if n < 0 else 1
        n = abs(n)
        sum = 0
        while n > 0:
            digit = n % 10
            sum += digit * sign
            n //= 10
        return sum

    return sum(1 for num in arr if sum_digits(num) > 0)
```

