from collections import Counter
from typing import Dict

def histogram(test: str) -> Dict[str, int]:
    freq = Counter(test.split())
    if freq.most_common()[0][1] == 1:
        return {}
    else:
        return {i: freq.get(i, 0) for i in freq if freq.get(i, 0) > 1}

