from collections import Counter

def histogram(test):
    test = test.split()
    if not test:
        return {}
    frequency = Counter(test)
    max_frequency = max(frequency.values())
    result = {char: max_frequency for char, freq in frequency.items() if freq == max_frequency}
    return result
