from sympy import primerange, isprime

def hex_key(num):
    prime_digits = ["B", "D", "E", "A"]
    count = 0
    for char in set(num.upper()):
        if char in prime_digits:
            count += isprime(int(char, 16))
        elif char.isdigit() and int(char, 16) in primerange(2, int(max(num.upper()), 16) + 1):
            count += 1
    return count
