from typing import Tuple, Union

def bf(planet1: str, planet2: str) -> Tuple[str, ...]:
    planets = {
        'Mercury': 1, 'Venus': 2, 'Earth': 3, 'Mars': 4, 'Jupiter': 5,
        'Saturn': 6, 'Uranus': 7, 'Neptune': 8
    }

    if planet1 not in planets or planet2 not in planets:
        return ()

    if planet1 == planet2:
        return ()

    planets_between = sorted([p for p in planets.keys() if planets[p] > planets[planet1] and planets[p] < planets[planet2]])
    return tuple(planets_between)
