import re

def simplify(x, n):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def fraction_to_int(s):
        num, denom = map(int, re.findall(r'\d+', s))
        return num * denom // gcd(num, denom)

    x_int = fraction_to_int(x)
    n_int = fraction_to_int(n)

    return x_int % n_int == 0
```

