import string

def check_dict_case(dict):
    if not dict:
        return False
    keys = set()
    for key in dict:
        if not isinstance(key, str):
            return False
        if key in string.ascii_letters:
            if not all(c.islower() for c in key):
                return False
            keys.add(key)
        else:
            if not all(c.isupper() for c in key):
                return False
            keys.add(key)
    return len(keys) == len(dict)
