import math

def largest_prime_digit_sum(lst):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    def largest_prime_number(lst):
        return max(num for num in lst if is_prime(num))

    primes = [num for num in lst if is_prime(num)]

    if not primes:
        return None  # Raise None if no prime numbers present.

    max_prime_num = largest_prime_number(lst)

    def digit_sum(num):
        return sum(int(digit) for digit in str(num))

    return digit_sum(max_prime_num)

