import math

def count_up_to(n):
    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        sqrt_num = math.isqrt(num)
        for i in range(3, sqrt_num + 1, 2):
            if num % i == 0:
                return False
        return True

    count = 0
    prime_numbers = []
    for possiblePrime in range(2, n):
        if is_prime(possiblePrime):
            prime_numbers.append(possiblePrime)
        count += 1
        if count == n:
            break
    if count < n:
        prime_numbers.extend(range(2, n))
    return prime_numbers
```

