from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def max_depth(s: str) -> int:
        if not s:  # empty string
            return 0
        stack = [0]
        max_d = 0
        for c in s:
            if c == '(':
                stack.append(len(stack))
            elif c == ')':
                max_d = max(max_d, stack.pop() - 1)
        return max_d

    return [max_depth(s) for s in paren_string.split()]  # split by space
```

