def specialFilter(nums):
    def is_odd_digit(num):
        return (num % 10) in [1, 3, 5, 7, 9]

    def is_odd_first_last_digit(num):
        return is_odd_digit(num) and is_odd_digit(int(str(num)[0]))

    return sum(1 for num in nums if is_odd_first_last_digit(num) and num > 10)
