from collections import defaultdict

def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = defaultdict(int)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count[(a[i], a[j], a[k])] = 1
    return len(count)
