from functools import reduce

def total_match(lst1, lst2):
    def char_count(s):
        return sum(c.isalpha() for c in s) if s else 0

    sum1 = reduce(char_count, lst1, 0)
    sum2 = reduce(char_count, lst2, 0)

    if sum1 <= sum2:
        return lst1 if sum1 == sum2 else lst1
    else:
        return lst2 if sum1 == sum2 else lst2
