def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shift = 2
    result = ''

    for char in s:
        if char.isalpha():
            index = alphabet.index(char.lower())
            shifted_index = index + shift
            if shifted_index > 25:
                shifted_index -= 26
            if char.isupper():
                result += alphabet[shifted_index].upper()
            else:
                result += alphabet[shifted_index]
        else:
            result += char

    return result
