def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shift = 2 * 2  # Rotate alphabet by 2 * 2 places
    shifted_alphabet = alphabet[shift:] + alphabet[:shift]
    encrypted_string = ''
    for char in s:
        if char.isalpha():
            if char.islower():
                encrypted_string += shifted_alphabet[(alphabet.index(char) + shift) % 26]
            else:
                encrypted_string += shifted_alphabet[(alphabet.index(char.lower()) + shift) % 26].upper()
        else:
            encrypted_string += char
    return encrypted_string
```

