def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    shift = ord(alphabet[0]) - ord('a') * 2
    result = ''

    for char in s:
        if char.isalpha():
            idx = min(ord(char.lower()) - ord('a'), 25)
            result += alphabet[(idx + shift - 1) % 26]
        else:
            result += char

    if s.isupper():
        result = result.upper()

    return result
