from typing import Union

def fib4(n: int) -> Union[int, None]:
    if n < 0:
        return None
    elif n == 0 or n == 1:
        return 0
    elif n == 2:
        return 2
    else:
        fib4_values = [0, 0, 2, 0]
        for i in range(3, n + 1):
            fib4_values.append(fib4_values[i - 1] + fib4_values[i - 2] + fib4_values[i - 3] + fib4_values[i - 4])
        return fib4_values[n]
