from math import sqrt

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        str_i = str(i)
        if str_i == str_i[::-1] and sqrt(i) % 1 == 0:
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return tuple((even_count, odd_count))
