from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """ 
    Input to this function is a string containing multiple groups of nested parentheses. Your goal is to 
    separate those group into separate strings and return the list of those. Separate groups are balanced 
    (each open brace is properly closed) and not nested within each other 
    Ignore any spaces in the input string. 
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    stack = []
    result = []
    for char in paren_string.replace(" ", ""):
        if char == "(":
            stack.append(char)
        elif char == ")":
            if stack:
                stack.pop()
            else:
                result.append(char)
        elif char != ")":
            if not stack:
                result.append(char)
    return result
```

