from collections import Counter

def reverse_delete(s, c):
    s_counter = Counter(s)
    c_counter = Counter(c)
    s_with_c_deleted = ''
    for char in s:
        if s_counter[char] == 0 or char not in c_counter:
            s_with_c_deleted += char
    is_palindrome = s_with_c_deleted == s_with_c_deleted[::-1]
    return (s_with_c_deleted, is_palindrome)
```

