from collections import deque

def reverse_delete(s, c):
    s1, s2 = s.split(c) if c in s else (s, None)
    queue = deque(s1)
    stack = []

    while queue:
        ch = queue.popleft()
        if ch in stack:
            queue.append(ch)
        elif ch not in c:
            stack.append(ch)
        else:
            queue.appendleft(ch)

    if not stack: 
        return (s1, True)
    else:
        return ("".join(stack), False)
