import itertools

def bf(planet1, planet2):
    planets = ['Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune']
    ordered_planets = ['Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune']
    planet_order = {'Mercury': 1, 'Venus': 2, 'Earth': 3, 'Mars': 4, 'Jupiter': 5, 'Saturn': 6, 'Uranus': 7, 'Neptune': 8}
    planet_ids = list(planet_order.values())

    if planet1 not in planets or planet2 not in planets:
        return ()

    indices = [planet_order[planet1], planet_order[planet2]]
    indices.sort()

    mid_index = (indices[1] + indices[0]) // 2

    result = tuple([p for p in ordered_planets if idx <= mid_index < idx + 1])

    if len(result) == 0:
        return ()

    return tuple(result)


